#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    ll a,m,p,q,r,s;
    int tc=0;
    while(cin>>a>>m>>p>>q>>r>>s){
        if(a==0&&m==0&&p==0&&q==0&&r==0&&s==0) break;
        tc++;
        auto check=[&](vector<pair<ll,ll>>& st){
            for(auto&pr:st) if(pr.first>=r && pr.second<=s) return true;
            return false;
        };
        auto capMul=[&](ll x, ll y)->ll{
            if(y!=0 && x > (ll)4e18/y) return (ll)4e18;
            return x*y;
        };
        auto prune=[&](vector<pair<ll,ll>> st){
            vector<pair<ll,ll>> filtered;
            for(auto&pr:st) if(pr.second<=s) filtered.push_back(pr);
            sort(filtered.begin(), filtered.end(), [](auto&x,auto&y){
                return x.first>y.first || (x.first==y.first && x.second<y.second);
            });
            vector<pair<ll,ll>> res;
            ll minHi=LLONG_MAX;
            for(auto&pr:filtered) if(pr.second<minHi){ res.push_back(pr); minHi=pr.second; }
            return res;
        };
        vector<pair<ll,ll>> cur = prune({{p,q}});
        int depth=0;
        bool solved = check(cur);
        int maxDepth=300;
        while(!solved && depth<maxDepth && !cur.empty()){
            depth++;
            vector<pair<ll,ll>> next;
            for(auto&pr:cur){
                ll lo=pr.first, hi=pr.second;
                next.push_back({lo+a, hi+a});
                next.push_back({capMul(lo,m), capMul(hi,m)});
            }
            cur = prune(next);
            solved = check(cur);
        }
        if(!solved){ cout<<"Case "<<tc<<": impossible\n"; continue; }
        function<bool(ll,ll,int)> canReach = [&](ll lo, ll hi, int rem)->bool{
            vector<pair<ll,ll>> st = prune({{lo,hi}});
            if(check(st)) return true;
            for(int i=0;i<rem;i++){
                vector<pair<ll,ll>> nx;
                for(auto&pr:st){
                    nx.push_back({pr.first+a, pr.second+a});
                    nx.push_back({capMul(pr.first,m), capMul(pr.second,m)});
                }
                st = prune(nx);
                if(check(st)) return true;
                if(st.empty()) return false;
            }
            return false;
        };
        string ops="";
        ll lo=p, hi=q;
        for(int i=0;i<depth;i++){
            int rem = depth-i-1;
            ll loA=lo+a, hiA=hi+a;
            bool okA = (hiA<=s) && (rem==0 ? (loA>=r) : canReach(loA,hiA,rem));
            if(okA){ ops+='A'; lo=loA; hi=hiA; continue; }
            lo=capMul(lo,m); hi=capMul(hi,m);
            ops+='M';
        }
        cout<<"Case "<<tc<<": ";
        if(ops.empty()){ cout<<"empty\n"; continue; }
        string outp;
        size_t i=0;
        while(i<ops.size()){
            size_t j=i;
            while(j<ops.size() && ops[j]==ops[i]) j++;
            if(!outp.empty()) outp+=" ";
            outp += to_string((int)(j-i)) + ops[i];
            i=j;
        }
        cout<<outp<<"\n";
    }
}

